const heroData = "";
const heroEventData = "";
const coinData = "";
const pgLogoData = "";
const priceGoldData = "";
const gallery3Data = "";
const gallery4Data = "";
const fbPost1Data = "";
const html = page
  .replaceAll("__PGLOGO__", `data:image/png;base64,${pgLogoData}`)
  .replaceAll("__PRICE_GOLD__", `data:image/jpeg;base64,${priceGoldData}`)
